Let $\mathcal{X} = \prod_{i=1}^m \mathcal{X}_i$ where each $\mathcal{X}_i\subset \mathbb{R}^{n_i}$
     is either the unit ball $B_{n_i}$ or the standard simplex $\Delta_{n_i}$. We fix a positive integer $k$ and consider any $r > 2(\max\{n_1,\dots,n_m\}+1)k$. Let $\lambda= (\lambda^{(1)},\dots,\lambda^{(m)})$, 
     where $\lambda^{(i)}$ is  the sequence associated with the simple set $\mathcal{X}_i$ satisfying the conditions as in Lemma~2.6. Then the perturbed CD kernel $C_{2r}[\mathcal{X},\mu,\lambda]$ and its associated operator $\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]$ on $\mathbb{R}[\mathbf{x}]_k$ satisfies the following conditions:
     \begin{align}
        &\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda](1) =1,\tag{P1}\\
        &\mathbf{C}_{2r}[\mathcal{X},\mu,\lambda]f \in \mathcal{T}(\mathcal{X})_{2mr} \quad \forall f \in \mathbb{R}[\mathbf{x}]_k \; \mbox{such that}\;
        f(\mathbf{x}) \geq 0 \ \forall \mathbf{x} \in \mathcal{X},\tag{P2}\\
        &\|\mathbf{C}_{2r}^{-1}f-f\|_{\mathcal{X}} \leq 
          2^{m-1}\binom{k+m-1}{m-1}\left(\sum_{i=1}^m c(n_i,k)\right)\frac{\Lambda(\mathcal{X},k) \|f\|_{\mathcal{X}}}{r^2}, \ \forall \; f\in \mathbb{R}[\mathbf{x}]_k,
        \tag{P3}
     \end{align}
     where $\Lambda(\mathcal{X},k)$ is the harmonic constant defined in 
     (3.4).

Consider the polynomial optimization problem 
    \begin{displaymath}
    f_{\min} := \underset{\mathbf{x} \in \mathcal{X}}{\min}\ f(\mathbf{x}),
    \end{displaymath}
    where $\mathcal{X}$ is a product of unit balls and standard simplexes as in Theorem 
    3.3. Let  $k = {\rm deg} (f)$ and
    $f_{\max} = \max \{f(\mathbf{x}): \mathbf{x}\in\mathcal{X}\}$. Then we have that 
    the convergence rate of the Schmüdgen-type moment-SOS hierarchies (2.5) and (2.4) is $\mathrm{O}(1/r^2)$ with the following bound for any $r \geq 2m(\max\{n_1,\ldots,n_m\}+1)k+m$, 
    \begin{eqnarray*}
       0 &\leq& f_{\min} - \mathrm{mlb}(f,\mathcal{T}(\mathcal{X}))_{r} \leq f_{\min} - \mathrm{lb}(f,\mathcal{T}(\mathcal{X}))_{r}
       \;\leq\;
       \Gamma(\mathcal{X},k)\frac{(f_{\max}-f_{\min})}{(r-m)^2},
    \end{eqnarray*}
    where the constant
$\Gamma(\mathcal{X},k)= m^2\, 2^{m-1} \binom{k+m-1}{m-1}\left(\sum_{i=1}^m c(n_i,k)\right)\Lambda(\mathcal{X},k)$
is dependent on the domain $\mathcal{X}$ and the degree $k$.

Let $\mathcal{X}\subset \mathbb{R}^n$ be a compact set that is a product $\Pi_{i=1}^m\mathcal{X}_i$ where each $\mathcal{X}_i\subset \mathbb{R}^{n_i}$ is either the unit ball $B_{n_i}$ or standard simplex $\Delta_{n_i}$. We assume that there exists $R$ such that $\mathcal{X} \subset \mathbb{B}_R$, and the inequality, $R^2 -\|\mathbf{x}\|^2 \geq0$, is included in the definition of $\mathcal{X}$. For a fixed $k=2l$ and $r \geq 2m(\max\{n_1,\dots,n_m\}+1)k+m$, the Hausdorff distance $\mathbf{d}_k(\mathcal{T}(\mathcal{X})_{2r})$ admits the following upper bound:
    \begin{equation}
        \mathbf{d}_k(\mathcal{T}(\mathcal{X})_{2r}) \leq \Gamma(\mathcal{X},k)\dfrac{2\gamma(R,n,k)}{(r-m)^2}.
    \end{equation}
    Here, the parameter $\gamma(R,n,k)$ is the radius of the ball centered at the origin that
    contains $\mathcal{M}_k(\mathcal{T}(\mathbb{B}_R)_{2r})$, and it depends polynomially on $n$ and $k$.

Let $\mathcal{X} = \prod_{i=1}^m\mathcal{X}_i$, where each $\mathcal{X}_i \subset \mathbb{R}^{n_i}$ is either the unit ball $B_{n_i}$ or the standard simplex $\Delta_{n_i}$.
       We choose the reference measure $\mu =\otimes_{i=1}^m\mu_i$ for $\mathcal{X}$, where $\mu_i$ is the reference measure on $\mathcal{X}_i$ as in Table~tab:measure. 
       Let $n =\sum_{i=1}^m n_i$. For any $i \in [m]$, let $\mathit{y}^{(i)}=\big(\mathit{y}^{(i)}_{\alpha^{(i)}\in \mathbb{N}^{n_i}}\big)$ be the moment sequence with respect to $\mu_i$. 
    Then the moment sequence $\mathit{y}=(\mathit{y}_{\alpha\in \mathbb{N}^n})$ with respect to $\mu$ is defined as follows: for any $\alpha= (\alpha^{(1)},\dots,\alpha^{(m)}) \in \mathbb{N}^n$ with $\alpha^{(i)} \in \mathbb{N}^n_i\; \forall i \in [m]$, the $\alpha-$component of $\mathit{y}$ is defined by 
    \begin{displaymath}
        \mathit{y}_{\alpha}= \prod_{i=1}^m \mathit{y}^{(i)}_{\alpha^{(i)}}.
    \end{displaymath}
    In addition, for a given $f(\mathbf{x})\in \mathbb{R}[\mathbf{x}]$ of degree $k$, consider the POP 
    \begin{equation*}
    f_{\min} := \min_{\mathbf{x} \in \mathcal{X}}f(\mathbf{x}).
    \end{equation*}
   Then for any integer $r > 2(\max\{n_1,\ldots,n_m\}+1)k$,
   the following inequality holds: 
    \begin{displaymath}
        \mathrm{ub}(f,\mathcal{T}(\mathcal{X}))_{mr}-f_{\min} \leq \binom{k+m-1}{m-1}\left(\sum_{i=1}^m c(n_i,k)\right)\frac{\Lambda(\mathcal{X},k)\|f\|_{\mathcal{X}}}{r^2}.
    \end{displaymath}
    Consequently, the convergence rate of the Schm\"udgen-type hierarchy of upper-bounds over the product of unit balls and standard simplexes is
     $\mathrm{O}(1/r^2)$.

Let $\mathcal{X}$ be a semi-algebraic set defined in (4.1), $\mathcal{Y}=\Pi_{i=1}^s\mathcal{Y}_i$ is a product of $s$ simple sets $\mathcal{Y}_i\subset \mathbb{R}^{n_i}$ as expressed in (4.2). We assume that the inequality $g_0(\mathbf{x}) = R^2 -\|\mathbf{x}\|^2 \geq 0$ is added to the description of $\mathcal{X}$. For any $k = 2l \in\mathbb{N}$ and $r \in \mathbb{N}$ such that $k\geq 4d$ and $r \geq 2s(\max\{n_1,\dots,n_s\}+1)k+s$,  where $d$ is defined in (4.3), the Hausdorff distance $\mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r}) := \mathbf{d}(\mathcal{M}_k(\mathcal{R}(\mathcal{X})_{2r}),\mathcal{M}_k(\mathcal{X})) $ admits an upper bound as follows:
    \begin{displaymath}
        \mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r}) \leq 
        \dfrac{2\gamma(R,n,k)\Gamma(\mathcal{Y},k)}{(r-s)^2}+ cL(R,k)\left(\dfrac{2\gamma(R,n,k)\,
        \Gamma(\mathcal{Y},k)}{(r-s)^2}\right)^{\textit{\L}/2}
        \left(\sum_{i=1}^p\|h_i^2\|_{1}\right)^{\textit{\L}/2}.
    \end{displaymath}
    Here, $L(R,k)$ is the Lipschitz number of $\mathbf{v}_k(\mathbf{x})$ on the compact set $\mathbb{B}_R$, $\Gamma(\mathcal{Y},k)$ is a parameter defined in Theorem~3.5. In short, the error of  $k$-truncated pseudo-moment sequences in the $r$-th level of Schmüdgen-type moment hierarchy is $\mathrm{O}(1/r^{\textit{\L}})$.

Let $\mathcal{X} \in \mathbb{R}^n$ be a compact basic semi-algebraic set defined as in (eq-CX). For any positive integers $k=2l$ and $r$ such that $t = \lfloor r/(2d) \rfloor$, $l \geq 2d$, and $t \geq 4(\max\{n,m\}+1)k+2$ the Hausdorff distance $\mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r})$ admits the following bound:
     \begin{multline*}
          \mathbf{d}_k(\mathcal{R}(\mathcal{X})_{2r}) \leq \Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)\dfrac{(2d)^2}{(r-4d)^2}\\+\frac{cL(R,k)(2d)^{\textit{\L}}}{(r-4d)^{\textit{\L}}}
            [\Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)]^{\textit{\L}/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}}.
     \end{multline*}
     Here, the parameter $L(R,k)$ is the Lipschitz number of $\mathbf{v}_k(\mathbf{x})$ on the simple set $\mathbb{B}_R$. In short, the error for the set of truncated pseudo-moment sequences $\mathcal{M}_k(\mathcal{R}(\mathcal{X})_{2r})$
     is $\mathrm{O}(1/r^{\textit{\L}})$.

Let $\mathcal{X}$ be the set and $k,r$ be the numbers defined as in Theorem~4.7. Then the following inequality holds:
     \begin{multline*}
          f_{\min}-\mathrm{lb}(f,\mathcal{R}(\mathcal{X}))_r \leq \Biggl[\Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)\dfrac{(2d)^2}{(r-4d)^2}\\+\frac{cL(R,k)(2d)^{\textit{\L}}}{(r-4d)^{\textit{\L}}}
            [\Gamma(\mathbb{B}_R \times \Delta_K^m,k)2\gamma(n+m,R+mK^2,k)]^{\textit{\L}/2}\left(m+\sum_{j=1}^m\|g_j\|_1+\sum_{i=1}^p\|h_i\|_1\right)^{\textit{\L}}\Biggr]\cdot \|f\|_1.
     \end{multline*}
     In conclusion, it is shown that the error for Schmüdgen-type truncated pseudo-moment sequences on a compact basic semi-algebraic $\mathcal{X}$ is $\mathrm{O}(1/r^{\textit{\L}})$, where $\textit{\L}$ is the Łojasiewicz exponent depending on the polynomial inequalities defining $\mathcal{X}$.

Let $\mathcal{X}$ be a polytope. Then the Łojasiewicz exponent of $\mathcal{X}$ is $1$. Consequently, we obtain the followings.
      \begin{enumerate}
            \item For any fixed positive integer $k$, the error $\mathbf{d}_k(\mathcal{T}(\mathcal{X})_{2r})$ of pseudo-moment sequences on $\mathcal{X}$ is of
            the order $\mathrm{O}(1/r)$. 
            \item The convergence rate of the reduced moment-SOS hierarchy (2.8),~(2.9), and the Schmüdgen-type moment-SOS hierarchy (2.4), (2.5) are of the order $\mathrm{O}(1/r)$.
      \end{enumerate}

Let $k,l$ and $r$ be positive integers such that $k=2l$ and $2r\geq k$. Then the Hausdorff distance $\mathbf{d}_k(\mathcal{Q}(S_R^{n-1})_{2r}) =\mathbf{d}_k(\mathcal{T}(S_R^{n-1})_{2r})$ admits the following upper bound:
    \begin{equation}
        \mathbf{d}_k(\mathcal{T}(S_R^{n-1})_{2r}) \leq   
        \left(1+ \frac{\sqrt{n}L(R,k)}{R} \right)\frac{2\gamma(R,n,k)\Gamma(\mathbb{B}_R,k)}{r^2}.
    \end{equation}

Consider the following POP on $S_R^{n-1}$:
    \begin{displaymath}
        \min_{\mathbf{x} \in S_R^{n-1}}f(\mathbf{x}),
    \end{displaymath}
    where $f(x)$ is a polynomial of degree $k$. Then the convergence rate of the moment-SOS hierarchy $\mathrm{mlb}(f,\mathcal{Q}(\mathcal{X}))_r$ and $\mathrm{lb}(f,\mathcal{Q}(\mathcal{X}))_r$ is of the order $\mathrm{O}(1/r^2)$.
